  CONSTRAINT `InventoryShipment_chk_1` CHECK ((`originFacilityID` <> `destinationFacilityID`)),
  CONSTRAINT `InventoryShipment_chk_2` CHECK (((`timeArrived` is null) or (`timeArrived` >= `timeSent`)))
