DROP TABLE IF EXISTS `InventoryShipmentContains`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `InventoryShipmentContains` (
  `shipmentID` int NOT NULL,
  `productID` int NOT NULL,
  `quantity` int NOT NULL,
  PRIMARY KEY (`shipmentID`,`productID`),
  KEY `productID` (`productID`),
  CONSTRAINT `InventoryShipmentContains_ibfk_1` FOREIGN KEY (`shipmentID`) REFERENCES `InventoryShipment` (`shipmentID`) ON DELETE CASCADE,
  CONSTRAINT `InventoryShipmentContains_ibfk_2` FOREIGN KEY (`productID`) REFERENCES `Product` (`productID`),
  CONSTRAINT `InventoryShipmentContains_chk_1` CHECK ((`quantity` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
