DROP TABLE IF EXISTS `OrderContains`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `OrderContains` (
  `orderID` int NOT NULL,
  `productID` int NOT NULL,
  `quantity` int NOT NULL,
  `unitPriceAtPurchase` decimal(10,2) NOT NULL,
  PRIMARY KEY (`orderID`,`productID`),
  KEY `productID` (`productID`),
  CONSTRAINT `OrderContains_ibfk_1` FOREIGN KEY (`orderID`) REFERENCES `Orders` (`orderID`) ON DELETE CASCADE,
  CONSTRAINT `OrderContains_ibfk_2` FOREIGN KEY (`productID`) REFERENCES `Product` (`productID`),
  CONSTRAINT `OrderContains_chk_1` CHECK ((`quantity` > 0)),
  CONSTRAINT `OrderContains_chk_2` CHECK ((`unitPriceAtPurchase` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
