--
-- Table structure for table `Orders`
--

DROP TABLE IF EXISTS `Orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Orders` (
  `orderID` int NOT NULL,
  `customerID` int NOT NULL,
  `shipmentID` int DEFAULT NULL,
  `orderDate` date NOT NULL,
  `street` varchar(255) NOT NULL,
  `city` varchar(100) NOT NULL,
  `province` varchar(100) NOT NULL,
  `postalCode` varchar(20) NOT NULL,
  `deliveryTier` varchar(50) NOT NULL,
  `estimatedDeliveryDate` date DEFAULT NULL,
  `actualDeliveryDate` date DEFAULT NULL,
  PRIMARY KEY (`orderID`),
  KEY `customerID` (`customerID`),
  KEY `shipmentID` (`shipmentID`),
  KEY `deliveryTier` (`deliveryTier`),
  KEY `idx_orders_date` (`orderDate`),
  CONSTRAINT `Orders_ibfk_1` FOREIGN KEY (`customerID`) REFERENCES `Customer` (`customerID`),
  CONSTRAINT `Orders_ibfk_2` FOREIGN KEY (`shipmentID`) REFERENCES `OrderShipment` (`shipmentID`),
  CONSTRAINT `Orders_ibfk_3` FOREIGN KEY (`deliveryTier`) REFERENCES `DeliveryTier` (`deliveryTier`) ON UPDATE CASCADE,
  CONSTRAINT `Orders_chk_1` CHECK (((`estimatedDeliveryDate` is null) or (`estimatedDeliveryDate` >= `orderDate`))),
  CONSTRAINT `Orders_chk_2` CHECK (((`actualDeliveryDate` is null) or (`actualDeliveryDate` >= `orderDate`))),
  CONSTRAINT `Orders_chk_3` CHECK (((`actualDeliveryDate` is null) or (`shipmentID` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

