DROP TABLE IF EXISTS `Product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Product` (
  `productID` int NOT NULL,
  `listingID` int NOT NULL,
  `supplierID` int NOT NULL,
  `productName` varchar(255) NOT NULL,
  `category` varchar(100) NOT NULL,
  `brand` varchar(100) DEFAULT NULL,
  `listingName` varchar(255) NOT NULL,
  `listingPrice` decimal(10,2) NOT NULL,
  `listingStatus` varchar(50) NOT NULL,
  `listingDate` date NOT NULL,
  PRIMARY KEY (`productID`),
  UNIQUE KEY `listingID` (`listingID`),
  KEY `supplierID` (`supplierID`),
  KEY `idx_product_category_status` (`category`,`listingStatus`),
  KEY `idx_product_listing_date` (`listingDate`),
  CONSTRAINT `Product_ibfk_1` FOREIGN KEY (`supplierID`) REFERENCES `Supplier` (`supplierID`) ON DELETE CASCADE,
  CONSTRAINT `Product_chk_1` CHECK ((`listingPrice` >= 0)),
  CONSTRAINT `Product_chk_2` CHECK ((`listingStatus` in (_utf8mb4'Active',_utf8mb4'Inactive')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
