--
-- Table structure for table `Refund`
--

DROP TABLE IF EXISTS `Refund`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Refund` (
  `orderID` int NOT NULL,
  `productID` int NOT NULL,
  `refundNumber` int NOT NULL,
  `refundDate` date NOT NULL,
  `refundReason` varchar(500) DEFAULT NULL,
  `refundQuantity` int NOT NULL,
  `refundAmount` decimal(10,2) NOT NULL,
  PRIMARY KEY (`orderID`,`productID`,`refundNumber`),
  CONSTRAINT `Refund_ibfk_1` FOREIGN KEY (`orderID`, `productID`) REFERENCES `OrderContains` (`orderID`, `productID`) ON DELETE CASCADE,
  CONSTRAINT `Refund_chk_1` CHECK ((`refundNumber` > 0)),
  CONSTRAINT `Refund_chk_2` CHECK ((`refundQuantity` > 0)),
  CONSTRAINT `Refund_chk_3` CHECK ((`refundAmount` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

